import matter from 'gray-matter';
import type { Frontmatter } from './types.js';

export interface ParsedDocument {
  frontmatter: Frontmatter;
  body: string;
}

/** Coerce a frontmatter `tags` value into a normalized, deduplicated string array. */
export function normalizeTags(value: unknown): string[] {
  let tags: string[] = [];
  if (Array.isArray(value)) {
    tags = value.map((t) => String(t));
  } else if (typeof value === 'string') {
    tags = value.split(',');
  }
  const seen = new Set<string>();
  const out: string[] = [];
  for (const raw of tags) {
    const t = raw.trim();
    if (!t) continue;
    const key = t.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(t);
  }
  return out;
}

/** Coerce a frontmatter `date` value (Date | string | number) into a Date, or null if absent/invalid. */
export function normalizeDate(value: unknown): Date | null {
  if (value instanceof Date) return isNaN(value.getTime()) ? null : value;
  if (typeof value === 'string' || typeof value === 'number') {
    const d = new Date(value);
    return isNaN(d.getTime()) ? null : d;
  }
  return null;
}

/** Turn arbitrary text into a URL-safe slug. */
export function slugify(text: string): string {
  return text
    .toLowerCase()
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '') // strip diacritics
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

/**
 * Parse a Markdown document with optional YAML frontmatter.
 * `fallbackTitle` is used when no `title` key is present (typically the filename).
 */
export function parseDocument(raw: string, fallbackTitle = 'Untitled'): ParsedDocument {
  const { data, content } = matter(raw);

  const frontmatter: Frontmatter = {
    ...data,
    title: typeof data.title === 'string' && data.title.trim() ? data.title.trim() : fallbackTitle,
    date: normalizeDate(data.date),
    tags: normalizeTags(data.tags),
    draft: data.draft === true,
    layout: typeof data.layout === 'string' && data.layout.trim() ? data.layout.trim() : 'default',
    description: typeof data.description === 'string' ? data.description : '',
  };
  if (typeof data.slug === 'string' && data.slug.trim()) {
    frontmatter.slug = slugify(data.slug);
  }

  return { frontmatter, body: content };
}

import { Marked } from 'marked';
import { markedHighlight } from 'marked-highlight';
import hljs from 'highlight.js';

const marked = new Marked(
  markedHighlight({
    langPrefix: 'hljs language-',
    highlight(code: string, lang: string): string {
      if (lang && hljs.getLanguage(lang)) {
        return hljs.highlight(code, { language: lang }).value;
      }
      return hljs.highlightAuto(code).value;
    },
  }),
);

marked.setOptions({ gfm: true });

/** Render Markdown to HTML with syntax-highlighted code blocks. */
export function renderMarkdown(markdown: string): string {
  return marked.parse(markdown) as string;
}

/** Derive a plain-text excerpt from markdown (first paragraph, capped). */
export function extractExcerpt(markdown: string, maxLength = 200): string {
  const firstBlock = markdown
    .split(/\n\s*\n/)
    .map((b) => b.trim())
    .find((b) => b && !b.startsWith('#') && !b.startsWith('```') && !b.startsWith('!['));
  if (!firstBlock) return '';
  const text = firstBlock
    .replace(/\[([^\]]*)\]\([^)]*\)/g, '$1') // links -> text
    .replace(/[*_`>#]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
  return text.length > maxLength ? `${text.slice(0, maxLength - 1).trimEnd()}\u2026` : text;
}

import Handlebars from 'handlebars';
import { promises as fs } from 'node:fs';
import path from 'node:path';

export interface TemplateEngine {
  /** Render the named layout (without .hbs extension) with the given context. */
  render(layout: string, context: Record<string, unknown>): string;
  hasLayout(layout: string): boolean;
}

/**
 * Template directory convention:
 *   templates/layouts/*.hbs   -> layouts, selected via frontmatter `layout` (default: "default")
 *   templates/partials/*.hbs  -> partials, referenced as {{> name}}
 *
 * Layouts may themselves declare a parent via `{{!< parent}}` on the first line;
 * the child's output is provided to the parent as `{{{body}}}`.
 */
export async function createTemplateEngine(templateDir: string): Promise<TemplateEngine> {
  const hb = Handlebars.create();
  registerHelpers(hb);

  const layoutSources = await readTemplates(path.join(templateDir, 'layouts'));
  const partialSources = await readTemplates(path.join(templateDir, 'partials'));

  if (!layoutSources.has('default')) {
    throw new Error(`Missing required layout: ${path.join(templateDir, 'layouts', 'default.hbs')}`);
  }

  for (const [name, source] of partialSources) {
    hb.registerPartial(name, source);
  }

  const layouts = new Map<string, { template: Handlebars.TemplateDelegate; parent: string | null }>();
  for (const [name, source] of layoutSources) {
    const { parent, body } = extractParent(source);
    layouts.set(name, { template: hb.compile(body), parent });
  }

  function render(layout: string, context: Record<string, unknown>): string {
    let current = layouts.get(layout);
    if (!current) current = layouts.get('default')!;
    let output = current.template(context);
    const visited = new Set<string>([layout]);
    while (current.parent) {
      const parentName: string = current.parent;
      if (visited.has(parentName)) throw new Error(`Circular layout inheritance involving "${parentName}"`);
      visited.add(parentName);
      const parent = layouts.get(parentName);
      if (!parent) throw new Error(`Layout "${parentName}" (parent of another layout) not found`);
      output = parent.template({ ...context, body: new Handlebars.SafeString(output) });
      current = parent;
    }
    return output;
  }

  return { render, hasLayout: (l) => layouts.has(l) };
}

function extractParent(source: string): { parent: string | null; body: string } {
  const match = source.match(/^\{\{!<\s*([\w-]+)\s*\}\}\r?\n?/);
  if (match) return { parent: match[1], body: source.slice(match[0].length) };
  return { parent: null, body: source };
}

async function readTemplates(dir: string): Promise<Map<string, string>> {
  const out = new Map<string, string>();
  let entries: string[];
  try {
    entries = await fs.readdir(dir);
  } catch {
    return out; // directory may not exist (e.g. no partials)
  }
  for (const entry of entries) {
    if (!entry.endsWith('.hbs')) continue;
    const source = await fs.readFile(path.join(dir, entry), 'utf8');
    out.set(entry.replace(/\.hbs$/, ''), source);
  }
  return out;
}

export function registerHelpers(hb: typeof Handlebars): void {
  hb.registerHelper('formatDate', (date: unknown, format?: unknown) => {
    if (!(date instanceof Date) || isNaN(date.getTime())) return '';
    const fmt = typeof format === 'string' ? format : 'YYYY-MM-DD';
    const pad = (n: number) => String(n).padStart(2, '0');
    const months = [
      'January', 'February', 'March', 'April', 'May', 'June',
      'July', 'August', 'September', 'October', 'November', 'December',
    ];
    return fmt
      .replace(/YYYY/g, String(date.getUTCFullYear()))
      .replace(/MMMM/g, months[date.getUTCMonth()])
      .replace(/MM/g, pad(date.getUTCMonth() + 1))
      .replace(/DD/g, pad(date.getUTCDate()));
  });
  hb.registerHelper('isoDate', (date: unknown) =>
    date instanceof Date && !isNaN(date.getTime()) ? date.toISOString() : '',
  );
  hb.registerHelper('limit', (arr: unknown, n: unknown) =>
    Array.isArray(arr) ? arr.slice(0, Number(n) || 0) : [],
  );
  hb.registerHelper('eq', (a: unknown, b: unknown) => a === b);
  hb.registerHelper('join', (arr: unknown, sep: unknown) =>
    Array.isArray(arr) ? arr.join(typeof sep === 'string' ? sep : ', ') : '',
  );
}

import type { Page, SiteConfig } from './types.js';

export function escapeXml(text: string): string {
  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&apos;');
}

function absoluteUrl(baseUrl: string, url: string): string {
  return `${baseUrl.replace(/\/+$/, '')}${url}`;
}

/**
 * Generate an RSS 2.0 feed from the given pages.
 * Only pages with a date are included, newest first, capped at `limit`.
 */
export function generateRss(pages: Page[], config: SiteConfig, limit = 20): string {
  const items = pages
    .filter((p) => p.frontmatter.date !== null)
    .sort((a, b) => b.frontmatter.date!.getTime() - a.frontmatter.date!.getTime())
    .slice(0, limit);

  const lastBuildDate = (items[0]?.frontmatter.date ?? new Date()).toUTCString();

  const itemXml = items
    .map((p) => {
      const link = absoluteUrl(config.baseUrl, p.url);
      const description = p.frontmatter.description || p.excerpt;
      const categories = p.frontmatter.tags
        .map((t) => `      <category>${escapeXml(t)}</category>`)
        .join('\n');
      return [
        '    <item>',
        `      <title>${escapeXml(p.frontmatter.title)}</title>`,
        `      <link>${escapeXml(link)}</link>`,
        `      <guid isPermaLink="true">${escapeXml(link)}</guid>`,
        `      <pubDate>${p.frontmatter.date!.toUTCString()}</pubDate>`,
        description ? `      <description>${escapeXml(description)}</description>` : null,
        categories || null,
        '    </item>',
      ]
        .filter((line): line is string => line !== null)
        .join('\n');
    })
    .join('\n');

  return `<?xml version="1.0" encoding="UTF-8"?>
<rss version="2.0" xmlns:atom="http://www.w3.org/2005/Atom">
  <channel>
    <title>${escapeXml(config.title)}</title>
    <link>${escapeXml(config.baseUrl)}</link>
    <description>${escapeXml(config.description)}</description>
    <lastBuildDate>${lastBuildDate}</lastBuildDate>
    <atom:link href="${escapeXml(absoluteUrl(config.baseUrl, '/feed.xml'))}" rel="self" type="application/rss+xml"/>
${itemXml}
  </channel>
</rss>
`;
}

import { promises as fs } from 'node:fs';
import path from 'node:path';
import { parseDocument, slugify } from './frontmatter.js';
import { renderMarkdown, extractExcerpt } from './markdown.js';
import { createTemplateEngine } from './templates.js';
import { generateRss } from './rss.js';
import type { BuildResult, Page, SiteConfig } from './types.js';

/** Recursively list files under `dir`, returning paths relative to `dir`. */
async function listFiles(dir: string, prefix = ''): Promise<string[]> {
  const out: string[] = [];
  const entries = await fs.readdir(dir, { withFileTypes: true });
  for (const entry of entries) {
    if (entry.name.startsWith('.')) continue;
    const rel = path.join(prefix, entry.name);
    if (entry.isDirectory()) {
      out.push(...(await listFiles(path.join(dir, entry.name), rel)));
    } else {
      out.push(rel);
    }
  }
  return out;
}

/** Map a source markdown path to a pretty output path and URL. */
export function outputPathFor(sourcePath: string, slugOverride?: string): { outputPath: string; url: string } {
  const parsed = path.parse(sourcePath);
  const name = slugOverride ?? slugify(parsed.name);
  const dir = parsed.dir.split(path.sep).filter(Boolean).map(slugify).join('/');
  if (name === 'index') {
    const outputPath = dir ? `${dir}/index.html` : 'index.html';
    return { outputPath, url: `/${dir ? `${dir}/` : ''}` };
  }
  const base = dir ? `${dir}/${name}` : name;
  return { outputPath: `${base}/index.html`, url: `/${base}/` };
}

async function loadPage(sourceDir: string, sourcePath: string): Promise<Page> {
  const raw = await fs.readFile(path.join(sourceDir, sourcePath), 'utf8');
  const fallbackTitle = path.parse(sourcePath).name;
  const { frontmatter, body } = parseDocument(raw, fallbackTitle);
  const { outputPath, url } = outputPathFor(sourcePath, frontmatter.slug);
  const html = renderMarkdown(body);
  const excerpt = frontmatter.description || extractExcerpt(body);
  return { sourcePath, outputPath, url, frontmatter, body, html, excerpt };
}

/** Collect pages grouped by tag (tag display name preserved from first occurrence). */
export function collectTags(pages: Page[]): Record<string, Page[]> {
  const tags: Record<string, Page[]> = {};
  for (const page of pages) {
    for (const tag of page.frontmatter.tags) {
      const key = tag.toLowerCase();
      (tags[key] ??= []).push(page);
    }
  }
  return tags;
}

async function writeFile(outDir: string, relPath: string, content: string): Promise<void> {
  const abs = path.join(outDir, relPath);
  await fs.mkdir(path.dirname(abs), { recursive: true });
  await fs.writeFile(abs, content, 'utf8');
}

export interface BuildOptions {
  /** Extra HTML injected before </body> of every page (used for live reload). */
  injectHtml?: string;
}

export async function build(config: SiteConfig, options: BuildOptions = {}): Promise<BuildResult> {
  const engine = await createTemplateEngine(config.templateDir);
  const written: string[] = [];

  if (config.clean) {
    await fs.rm(config.outDir, { recursive: true, force: true });
  }
  await fs.mkdir(config.outDir, { recursive: true });

  const files = await listFiles(config.sourceDir);
  const markdownFiles = files.filter((f) => f.endsWith('.md'));
  const assetFiles = files.filter((f) => !f.endsWith('.md'));

  let pages = await Promise.all(markdownFiles.map((f) => loadPage(config.sourceDir, f)));
  if (!config.includeDrafts) {
    pages = pages.filter((p) => !p.frontmatter.draft);
  }

  // Newest first; undated pages sort last.
  const posts = pages
    .filter((p) => p.frontmatter.date !== null)
    .sort((a, b) => b.frontmatter.date!.getTime() - a.frontmatter.date!.getTime());
  const tags = collectTags(pages);
  const tagList = Object.keys(tags)
    .sort()
    .map((t) => ({ name: t, url: `/tags/${slugify(t)}/`, count: tags[t].length }));

  const site = {
    title: config.title,
    description: config.description,
    baseUrl: config.baseUrl,
    tags: tagList,
  };
  const finalize = (html: string) =>
    options.injectHtml ? injectBeforeBodyEnd(html, options.injectHtml) : html;

  // Content pages.
  for (const page of pages) {
    const html = engine.render(page.frontmatter.layout, {
      ...page.frontmatter,
      content: page.html,
      excerpt: page.excerpt,
      url: page.url,
      page,
      site,
      posts,
      pages,
    });
    await writeFile(config.outDir, page.outputPath, finalize(html));
    written.push(page.outputPath);
  }

  // Tag index pages.
  const tagLayout = engine.hasLayout('tag') ? 'tag' : 'default';
  for (const [tag, tagged] of Object.entries(tags)) {
    const outputPath = `tags/${slugify(tag)}/index.html`;
    const html = engine.render(tagLayout, {
      title: `Tag: ${tag}`,
      tag,
      posts: tagged
        .slice()
        .sort((a, b) => (b.frontmatter.date?.getTime() ?? 0) - (a.frontmatter.date?.getTime() ?? 0)),
      site,
      url: `/tags/${slugify(tag)}/`,
    });
    await writeFile(config.outDir, outputPath, finalize(html));
    written.push(outputPath);
  }

  // All-tags index.
  if (tagList.length > 0) {
    const layout = engine.hasLayout('tags') ? 'tags' : 'default';
    const html = engine.render(layout, { title: 'Tags', tags: tagList, site, url: '/tags/' });
    await writeFile(config.outDir, 'tags/index.html', finalize(html));
    written.push('tags/index.html');
  }

  // RSS feed.
  await writeFile(config.outDir, 'feed.xml', generateRss(pages, config));
  written.push('feed.xml');

  // Pass through non-markdown assets (images, css, ...).
  for (const asset of assetFiles) {
    const dest = path.join(config.outDir, asset);
    await fs.mkdir(path.dirname(dest), { recursive: true });
    await fs.copyFile(path.join(config.sourceDir, asset), dest);
    written.push(asset);
  }

  return { pages, tags, written };
}

export function injectBeforeBodyEnd(html: string, snippet: string): string {
  const idx = html.lastIndexOf('</body>');
  if (idx === -1) return html + snippet;
  return html.slice(0, idx) + snippet + html.slice(idx);
}

import http from 'node:http';
import { promises as fs } from 'node:fs';
import path from 'node:path';
import chokidar from 'chokidar';
import { WebSocketServer, WebSocket } from 'ws';
import { build } from './build.js';
import type { SiteConfig } from './types.js';

const MIME: Record<string, string> = {
  '.html': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.json': 'application/json',
  '.xml': 'application/xml; charset=utf-8',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.gif': 'image/gif',
  '.svg': 'image/svg+xml',
  '.ico': 'image/x-icon',
  '.txt': 'text/plain; charset=utf-8',
  '.woff2': 'font/woff2',
};

export const LIVE_RELOAD_PATH = '/__livereload';

export function liveReloadScript(): string {
  return `<script>(() => {
  const connect = () => {
    const ws = new WebSocket((location.protocol === 'https:' ? 'wss://' : 'ws://') + location.host + '${LIVE_RELOAD_PATH}');
    ws.onmessage = (e) => { if (e.data === 'reload') location.reload(); };
    ws.onclose = () => setTimeout(connect, 1000);
  };
  connect();
})();</script>`;
}

/** Resolve a request URL to a file within root, guarding against path traversal. */
export async function resolveFile(root: string, urlPath: string): Promise<string | null> {
  const decoded = decodeURIComponent(urlPath.split('?')[0]);
  const safe = path.normalize(decoded).replace(/^(\.\.[/\\])+/, '');
  let filePath = path.join(root, safe);
  if (!filePath.startsWith(path.resolve(root))) return null;
  try {
    const stat = await fs.stat(filePath);
    if (stat.isDirectory()) filePath = path.join(filePath, 'index.html');
    await fs.access(filePath);
    return filePath;
  } catch {
    return null;
  }
}

export interface DevServer {
  close(): Promise<void>;
  port: number;
}

export async function serve(config: SiteConfig): Promise<DevServer> {
  const inject = liveReloadScript();
  const doBuild = async () => {
    try {
      await build(config, { injectHtml: inject });
      console.log(`[sitegen] built ${new Date().toLocaleTimeString()}`);
    } catch (err) {
      console.error('[sitegen] build failed:', err instanceof Error ? err.message : err);
    }
  };
  await doBuild();

  const server = http.createServer(async (req, res) => {
    const filePath = await resolveFile(config.outDir, req.url ?? '/');
    if (!filePath) {
      res.writeHead(404, { 'Content-Type': 'text/html; charset=utf-8' });
      res.end('<h1>404 Not Found</h1>');
      return;
    }
    const type = MIME[path.extname(filePath).toLowerCase()] ?? 'application/octet-stream';
    res.writeHead(200, { 'Content-Type': type });
    res.end(await fs.readFile(filePath));
  });

  const wss = new WebSocketServer({ server, path: LIVE_RELOAD_PATH });
  const broadcast = () => {
    for (const client of wss.clients) {
      if (client.readyState === WebSocket.OPEN) client.send('reload');
    }
  };

  let timer: NodeJS.Timeout | null = null;
  const watcher = chokidar.watch([config.sourceDir, config.templateDir], {
    ignoreInitial: true,
  });
  watcher.on('all', () => {
    // Debounce bursts of file events into a single rebuild + reload.
    if (timer) clearTimeout(timer);
    timer = setTimeout(async () => {
      await doBuild();
      broadcast();
    }, 100);
  });

  await new Promise<void>((resolve) => server.listen(config.port, resolve));
  const address = server.address();
  const port = typeof address === 'object' && address ? address.port : config.port;
  console.log(`[sitegen] serving ${config.outDir} at http://localhost:${port} (live reload on)`);

  return {
    port,
    async close() {
      if (timer) clearTimeout(timer);
      await watcher.close();
      wss.close();
      await new Promise<void>((resolve, reject) =>
        server.close((err) => (err ? reject(err) : resolve())),
      );
    },
  };
}

#!/usr/bin/env node
