import { describe, it, expect } from 'vitest';
import { parseDocument, normalizeTags, normalizeDate, slugify } from '../src/frontmatter.js';

describe('parseDocument', () => {
  it('parses full frontmatter', () => {
    const { frontmatter, body } = parseDocument(
      [
        '---',
        'title: My Post',
        'date: 2026-01-15',
        'tags: [a, b]',
        'draft: true',
        'layout: post',
        'description: Hi',
        '---',
        '',
        'Body text.',
      ].join('\n'),
    );
    expect(frontmatter.title).toBe('My Post');
    expect(frontmatter.date?.toISOString()).toBe('2026-01-15T00:00:00.000Z');
    expect(frontmatter.tags).toEqual(['a', 'b']);
    expect(frontmatter.draft).toBe(true);
    expect(frontmatter.layout).toBe('post');
    expect(frontmatter.description).toBe('Hi');
    expect(body.trim()).toBe('Body text.');
  });

  it('applies defaults when frontmatter is absent', () => {
    const { frontmatter, body } = parseDocument('Just text.', 'my-file');
    expect(frontmatter.title).toBe('my-file');
    expect(frontmatter.date).toBeNull();
    expect(frontmatter.tags).toEqual([]);
    expect(frontmatter.draft).toBe(false);
    expect(frontmatter.layout).toBe('default');
    expect(body).toBe('Just text.');
  });

  it('treats non-true draft values as false', () => {
    const { frontmatter } = parseDocument('---\ndraft: "yes"\n---\nx');
    expect(frontmatter.draft).toBe(false);
  });

  it('passes through extra keys and slugifies slug', () => {
    const { frontmatter } = parseDocument('---\nauthor: Ada\nslug: My Fancy Slug!\n---\nx');
    expect(frontmatter.author).toBe('Ada');
    expect(frontmatter.slug).toBe('my-fancy-slug');
  });
});

describe('normalizeTags', () => {
  it('accepts arrays', () => {
    expect(normalizeTags(['a', 'b'])).toEqual(['a', 'b']);
  });
  it('accepts comma-separated strings', () => {
    expect(normalizeTags('a, b , c')).toEqual(['a', 'b', 'c']);
  });
  it('dedupes case-insensitively and drops empties', () => {
    expect(normalizeTags(['TS', 'ts', '', '  '])).toEqual(['TS']);
  });
  it('returns [] for missing/invalid values', () => {
    expect(normalizeTags(undefined)).toEqual([]);
    expect(normalizeTags(42)).toEqual([]);
  });
});

describe('normalizeDate', () => {
  it('accepts Date, string, and rejects invalid', () => {
    expect(normalizeDate(new Date('2026-01-01'))?.getUTCFullYear()).toBe(2026);
    expect(normalizeDate('2026-06-01')?.getUTCMonth()).toBe(5);
    expect(normalizeDate('not a date')).toBeNull();
    expect(normalizeDate(undefined)).toBeNull();
  });
});

describe('slugify', () => {
  it('lowercases, strips diacritics and symbols', () => {
    expect(slugify('Héllo, Wörld!')).toBe('hello-world');
    expect(slugify('  --A  B--  ')).toBe('a-b');
  });
});

import { describe, it, expect } from 'vitest';
import { renderMarkdown, extractExcerpt } from '../src/markdown.js';

describe('renderMarkdown', () => {
  it('renders basic markdown', () => {
    const html = renderMarkdown('# Title\n\nSome **bold** text.');
    expect(html).toContain('<h1');
    expect(html).toContain('<strong>bold</strong>');
  });

  it('syntax-highlights fenced code blocks with a language', () => {
    const html = renderMarkdown('```ts\nconst x: number = 1;\n```');
    expect(html).toContain('class="hljs language-ts"');
    expect(html).toContain('hljs-'); // token spans present
  });

  it('auto-highlights code blocks without a language', () => {
    const html = renderMarkdown('```\nfunction f() { return 1; }\n```');
    expect(html).toContain('<pre><code');
    expect(html).toContain('hljs-');
  });
});

describe('extractExcerpt', () => {
  it('uses the first paragraph, skipping headings', () => {
    expect(extractExcerpt('# H\n\nFirst para.\n\nSecond.')).toBe('First para.');
  });
  it('strips inline markdown', () => {
    expect(extractExcerpt('Some *emphasis* and a [link](http://x).')).toBe(
      'Some emphasis and a link.',
    );
  });
  it('truncates long text with an ellipsis', () => {
    const out = extractExcerpt('word '.repeat(100), 50);
    expect(out.length).toBeLessThanOrEqual(50);
    expect(out.endsWith('\u2026')).toBe(true);
  });
});

import { describe, it, expect, beforeAll } from 'vitest';
import { promises as fs } from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import Handlebars from 'handlebars';
import { createTemplateEngine, registerHelpers } from '../src/templates.js';

async function makeTemplates(files: Record<string, string>): Promise<string> {
  const dir = await fs.mkdtemp(path.join(os.tmpdir(), 'sitegen-tpl-'));
  for (const [rel, content] of Object.entries(files)) {
    const abs = path.join(dir, rel);
    await fs.mkdir(path.dirname(abs), { recursive: true });
    await fs.writeFile(abs, content);
  }
  return dir;
}

describe('createTemplateEngine', () => {
  it('renders a layout with context', async () => {
    const dir = await makeTemplates({
      'layouts/default.hbs': '<h1>{{title}}</h1>{{{content}}}',
    });
    const engine = await createTemplateEngine(dir);
    expect(engine.render('default', { title: 'Hi', content: '<p>x</p>' })).toBe(
      '<h1>Hi</h1><p>x</p>',
    );
  });

  it('registers and renders partials', async () => {
    const dir = await makeTemplates({
      'layouts/default.hbs': '{{> nav}}<main>{{{content}}}</main>',
      'partials/nav.hbs': '<nav>{{site.title}}</nav>',
    });
    const engine = await createTemplateEngine(dir);
    expect(engine.render('default', { site: { title: 'S' }, content: 'c' })).toBe(
      '<nav>S</nav><main>c</main>',
    );
  });

  it('supports layout inheritance via {{!< parent}}', async () => {
    const dir = await makeTemplates({
      'layouts/default.hbs': '<html>{{{body}}}</html>',
      'layouts/post.hbs': '{{!< default}}\n<article>{{{content}}}</article>',
    });
    const engine = await createTemplateEngine(dir);
    expect(engine.render('post', { content: '<p>x</p>' })).toBe(
      '<html><article><p>x</p></article></html>',
    );
  });

  it('falls back to default for unknown layouts', async () => {
    const dir = await makeTemplates({ 'layouts/default.hbs': 'D:{{title}}' });
    const engine = await createTemplateEngine(dir);
    expect(engine.render('nope', { title: 't' })).toBe('D:t');
    expect(engine.hasLayout('nope')).toBe(false);
    expect(engine.hasLayout('default')).toBe(true);
  });

  it('throws when default layout is missing', async () => {
    const dir = await makeTemplates({ 'layouts/other.hbs': 'x' });
    await expect(createTemplateEngine(dir)).rejects.toThrow(/default\.hbs/);
  });

  it('detects circular layout inheritance', async () => {
    const dir = await makeTemplates({
      'layouts/default.hbs': '{{!< a}}\nD',
      'layouts/a.hbs': '{{!< default}}\nA{{{body}}}',
    });
    const engine = await createTemplateEngine(dir);
    expect(() => engine.render('a', {})).toThrow(/[Cc]ircular/);
  });
});

describe('helpers', () => {
  const hb = Handlebars.create();
  beforeAll(() => registerHelpers(hb as unknown as typeof Handlebars));

  it('formatDate formats with a pattern', () => {
    const t = hb.compile('{{formatDate d "MMMM DD, YYYY"}}');
    expect(t({ d: new Date('2026-01-15T00:00:00Z') })).toBe('January 15, 2026');
  });
  it('formatDate defaults to ISO date and tolerates junk', () => {
    const t = hb.compile('{{formatDate d}}');
    expect(t({ d: new Date('2026-01-15T00:00:00Z') })).toBe('2026-01-15');
    expect(t({ d: 'junk' })).toBe('');
  });
  it('limit slices arrays', () => {
    const t = hb.compile('{{#each (limit xs 2)}}{{this}}{{/each}}');
    expect(t({ xs: [1, 2, 3] })).toBe('12');
  });
  it('eq and join work', () => {
    expect(hb.compile('{{#if (eq a "x")}}Y{{/if}}')({ a: 'x' })).toBe('Y');
    expect(hb.compile('{{join xs "|"}}')({ xs: ['a', 'b'] })).toBe('a|b');
  });
});
